#!/usr/bin/env python3
"""Shared deterministic helpers for post-Chapter-5 planning skills."""

from __future__ import annotations

import hashlib
import base64
import json
import os
import re
import signal
import shutil
import subprocess
import sys
import threading
import time
import uuid
from pathlib import Path
from typing import Any

RUNNER_SCHEMA = "newrouge.isolated-model-runner.v1"
SENSITIVE_CAPABILITY_KEYS = {
    "capability_ref",
    "capability_refs",
    "capability_id",
    "capability_ids",
    "capability_title",
    "capability_titles",
}


def load_json(path: Path, default: Any = None) -> Any:
    if not path.is_file():
        return default
    return json.loads(path.read_text(encoding="utf-8"))


def atomic_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    # Use a per-writer temporary name.  A shared ``.tmp`` path is unsafe when
    # independent worker threads/processes update the same journal on Windows:
    # one writer can replace or unlink the other's temporary file between
    # write and ``replace``.  The final rename remains atomic while each
    # writer owns its temporary inode.
    tmp = path.with_name(
        f"{path.name}.{os.getpid()}.{threading.get_ident()}.{uuid.uuid4().hex}.tmp"
    )
    try:
        tmp.write_text(
            json.dumps(payload, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
            newline="\n",
        )
        tmp.replace(path)
    finally:
        if tmp.exists():
            tmp.unlink(missing_ok=True)


def canonical_sha(payload: Any) -> str:
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(raw.encode("utf-8")).hexdigest()


def file_sha(path: Path) -> str:
    return "sha256:" + hashlib.sha256(path.read_bytes()).hexdigest()


def normalized_file_sha(path: Path) -> str:
    """Use the MVG runner's content identity across Git newline conversions."""
    from _mvg_manifest import manifest_sha256
    return manifest_sha256(path.read_bytes())


def text_sha(value: str) -> str:
    return "sha256:" + hashlib.sha256(value.encode("utf-8")).hexdigest()


def repo_path(root: Path, value: str | Path) -> Path:
    path = Path(value)
    resolved = path if path.is_absolute() else root / path
    resolved = resolved.resolve()
    if not resolved.is_relative_to(root.resolve()):
        raise ValueError(f"path escapes repository: {value}")
    return resolved


def relative(root: Path, path: Path) -> str:
    return path.resolve().relative_to(root.resolve()).as_posix()


def scrub_capability_answers_with_paths(
    value: Any,
    *,
    path: str = "$",
) -> tuple[Any, list[str]]:
    removed: list[str] = []
    if isinstance(value, list):
        output = []
        for index, item in enumerate(value):
            scrubbed, nested = scrub_capability_answers_with_paths(
                item, path=f"{path}[{index}]"
            )
            output.append(scrubbed)
            removed.extend(nested)
        return output, removed
    if isinstance(value, dict):
        output: dict[str, Any] = {}
        for key, item in value.items():
            key_text = str(key)
            child_path = f"{path}.{key_text}"
            if key_text in SENSITIVE_CAPABILITY_KEYS:
                removed.append(child_path)
                continue
            scrubbed, nested = scrub_capability_answers_with_paths(
                item, path=child_path
            )
            output[key_text] = scrubbed
            removed.extend(nested)
        return output, removed
    return value, removed


def scrub_capability_answers(value: Any) -> Any:
    scrubbed, _removed = scrub_capability_answers_with_paths(value)
    return scrubbed


def _write_model_batches(
    out_dir: Path,
    *,
    ledger: dict[str, Any],
    semantics: dict[str, Any],
    char_budget: int,
) -> dict[str, Any]:
    if char_budget < 1000:
        raise ValueError("Capability model batch char budget must be at least 1000")
    batches_dir = out_dir / "model-batches"
    batches_dir.mkdir(parents=True, exist_ok=True)
    clean_ledger = scrub_capability_answers(ledger)
    clean_semantics = scrub_capability_answers(semantics)
    requirements = [
        row for row in clean_semantics.get("requirements", [])
        if isinstance(row, dict) and str(row.get("requirement_id") or "").strip()
    ]
    by_block: dict[str, list[dict[str, Any]]] = {}
    for row in requirements:
        for block_id in row.get("source_block_ids", []):
            by_block.setdefault(str(block_id), []).append(row)

    payloads: list[dict[str, Any]] = []
    current_blocks: list[dict[str, Any]] = []
    current_requirements: dict[str, dict[str, Any]] = {}
    current_chars = 0
    seen_requirements: set[str] = set()

    def flush(*, oversize_blocks: list[str] | None = None) -> None:
        nonlocal current_blocks, current_requirements, current_chars
        if not current_blocks and not current_requirements:
            return
        payloads.append({
            "schema_version": "newrouge.capability-model-batch.v1",
            "blocks": current_blocks,
            "requirements": list(current_requirements.values()),
            "oversize_blocks": list(oversize_blocks or []),
        })
        current_blocks = []
        current_requirements = {}
        current_chars = 0

    for block in clean_ledger.get("blocks", []):
        if not isinstance(block, dict):
            continue
        block_id = str(block.get("block_id") or "")
        linked = by_block.get(block_id, [])
        item = {"block": block, "requirements": linked}
        item_chars = len(json.dumps(item, ensure_ascii=False))
        if current_blocks and current_chars + item_chars > char_budget:
            flush()
        if item_chars > char_budget:
            current_blocks = [block]
            current_requirements = {
                str(row["requirement_id"]): row for row in linked
            }
            seen_requirements.update(current_requirements)
            current_chars = item_chars
            flush(oversize_blocks=[block_id])
            continue
        current_blocks.append(block)
        current_chars += item_chars
        for row in linked:
            rid = str(row["requirement_id"])
            current_requirements[rid] = row
            seen_requirements.add(rid)
    flush()

    remaining = [
        row for row in requirements
        if str(row["requirement_id"]) not in seen_requirements
    ]
    current: list[dict[str, Any]] = []
    current_chars = 0
    for row in remaining:
        row_chars = len(json.dumps(row, ensure_ascii=False))
        if current and current_chars + row_chars > char_budget:
            payloads.append({
                "schema_version": "newrouge.capability-model-batch.v1",
                "blocks": [],
                "requirements": current,
                "oversize_blocks": [],
            })
            current = []
            current_chars = 0
        current.append(row)
        current_chars += row_chars
    if current:
        payloads.append({
            "schema_version": "newrouge.capability-model-batch.v1",
            "blocks": [],
            "requirements": current,
            "oversize_blocks": [],
        })

    rows = []
    for index, payload in enumerate(payloads, 1):
        payload["batch_index"] = index
        payload["batch_count"] = len(payloads)
        path = batches_dir / f"batch-{index:03d}.json"
        atomic_json(path, payload)
        rows.append({
            "path": f"model-batches/{path.name}",
            "sha256": file_sha(path),
            "block_ids": [
                str(row.get("block_id") or "")
                for row in payload["blocks"]
                if str(row.get("block_id") or "").strip()
            ],
            "requirement_ids": sorted({
                str(row.get("requirement_id") or "")
                for row in payload["requirements"]
                if str(row.get("requirement_id") or "").strip()
            }),
            "oversize_blocks": payload["oversize_blocks"],
        })
    index = {
        "schema_version": "newrouge.capability-model-batch-index.v1",
        "char_budget": char_budget,
        "batch_count": len(rows),
        "block_count": len([
            row for row in clean_ledger.get("blocks", []) if isinstance(row, dict)
        ]),
        "requirement_count": len(requirements),
        "batches": rows,
    }
    atomic_json(out_dir / "model-batches" / "batch-index.json", index)
    return index


def source_classification_signal(text: str) -> dict[str, Any]:
    terms = re.findall(r"(?i)\bcapabilit(?:y|ies)\b|能力|模块", text)
    return {"present": bool(terms), "term_count": len(terms)}


def build_blinded_analysis_bundle(
    root: Path,
    out_dir: Path,
    *,
    source_manifest_path: Path,
    ledger_path: Path,
    semantics_path: Path,
    task_view_paths: list[Path],
    readiness_summary: dict[str, Any],
    model_batch_char_budget: int = 160000,
    repository_identity: dict[str, Any] | None = None,
    capability_reference_path: Path | None = None,
) -> dict[str, Any]:
    manifest = load_json(source_manifest_path, {})
    ledger = load_json(ledger_path, {})
    semantics = load_json(semantics_path, {})
    if manifest.get("schema_version") != "chapter3.source-manifest.v1":
        raise ValueError("invalid source manifest")
    if ledger.get("schema_version") != "newrouge.source-blocks.v1":
        raise ValueError("invalid source block ledger")
    if semantics.get("schema_version") != "newrouge.semantic-requirements.v1":
        raise ValueError("invalid semantic requirements")

    if out_dir.exists():
        shutil.rmtree(out_dir)
    out_dir.mkdir(parents=True)
    files: dict[str, str] = {}
    classification: dict[str, Any] = {}
    authority_inputs: dict[str, str] = {}
    transformations: list[dict[str, Any]] = []

    for row in manifest.get("sources", []):
        if not isinstance(row, dict):
            continue
        value = str(row.get("path") or "").strip()
        if not value:
            continue
        source = repo_path(root, value)
        if not source.is_file():
            raise ValueError(f"missing declared source: {value}")
        target = out_dir / "sources" / value
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, target)
        files[f"sources/{value}"] = file_sha(target)
        authority_inputs[value] = normalized_file_sha(source)
        classification[value] = source_classification_signal(
            source.read_text(encoding="utf-8", errors="replace")
        )

    for name, source, payload in (
        ("source-manifest.v1.json", source_manifest_path, manifest),
        ("source-blocks.v1.json", ledger_path, ledger),
        ("semantic-requirements.v1.json", semantics_path, semantics),
    ):
        target = out_dir / name
        scrubbed, removed = scrub_capability_answers_with_paths(payload)
        atomic_json(target, scrubbed)
        files[name] = file_sha(target)
        authority_inputs[relative(root, source)] = normalized_file_sha(source)
        transformations.append({
            "source_path": relative(root, source),
            "analysis_path": name,
            "source_sha256": file_sha(source),
            "analysis_sha256": files[name],
            "removed_fields": removed,
        })

    task_dir = out_dir / "task-views"
    task_dir.mkdir(parents=True, exist_ok=True)
    for source in task_view_paths:
        payload = load_json(source, [])
        target = task_dir / source.name
        scrubbed, removed = scrub_capability_answers_with_paths(payload)
        atomic_json(target, scrubbed)
        analysis_name = f"task-views/{source.name}"
        files[analysis_name] = file_sha(target)
        authority_inputs[relative(root, source)] = normalized_file_sha(source)
        transformations.append({
            "source_path": relative(root, source),
            "analysis_path": analysis_name,
            "source_sha256": file_sha(source),
            "analysis_sha256": files[analysis_name],
            "removed_fields": removed,
        })

    # Task views carry descriptive/acceptance evidence, but completion status
    # is authoritative only in the master Taskmaster export. Include a compact
    # copy in the prepared bundle so runners can filter retired views without
    # treating a stale overlay status as the source of truth.
    master_source = root / ".taskmaster/tasks/tasks.json"
    if master_source.is_file():
        master_payload = load_json(master_source, {})
        master_rows = (master_payload.get("master") or {}).get("tasks") if isinstance(master_payload, dict) else None
        if master_rows is None and isinstance(master_payload, dict):
            master_rows = master_payload.get("tasks")
        if not isinstance(master_rows, list):
            raise ValueError("invalid master task export")
        if any(not isinstance(row, dict) for row in master_rows):
            raise ValueError("invalid master task export row")
        task_rows = [
                {
                    "id": row.get("id", row.get("taskmaster_id")),
                    "taskmaster_id": row.get("taskmaster_id", row.get("id")),
                    "status": row.get("status", "active"),
                }
                for row in master_rows
            ]
        # Keep the Taskmaster container shape while using the canonical
        # taskmaster_id/status projection. Consumers that understand the
        # compact top-level form remain supported by the compatibility helper.
        master_payload = {
            "schema_version": "newrouge.task-master-statuses.v1",
            "master": {"tasks": task_rows},
        }
        master_target = out_dir / "task-master.json"
        atomic_json(master_target, master_payload)
        files["task-master.json"] = file_sha(master_target)
        authority_inputs[relative(root, master_source)] = normalized_file_sha(master_source)
        transformations.append({
            "source_path": relative(root, master_source),
            "analysis_path": "task-master.json",
            "source_sha256": file_sha(master_source),
            "analysis_sha256": files["task-master.json"],
            "removed_fields": [],
        })

    batch_index = _write_model_batches(
        out_dir,
        ledger=ledger,
        semantics=semantics,
        char_budget=model_batch_char_budget,
    )
    files["model-batches/batch-index.json"] = file_sha(
        out_dir / "model-batches" / "batch-index.json"
    )
    for row in batch_index["batches"]:
        files[str(row["path"])] = str(row["sha256"])

    atomic_json(out_dir / "readiness-summary.json", readiness_summary)
    files["readiness-summary.json"] = file_sha(out_dir / "readiness-summary.json")
    if capability_reference_path is not None:
        # Explicit diagnostics are retained for migration/research callers, but
        # the normal Capability workflow deliberately omits this input so a
        # previous project's grouping cannot anchor a new project's model.
        reference = load_json(capability_reference_path, {})
        if reference.get("schema_version") != "newrouge.capabilities.v1":
            raise ValueError("invalid capability reference")
        target = out_dir / "capability-reference.v1.json"
        # Keep only granularity signals. Full historical descriptions and
        # source mappings consume model context and invite copying stale IDs.
        compact = {
            "schema_version": "newrouge.capability-reference.v1",
            "reference_capabilities": [
                {
                    "capability_id": row.get("capability_id"),
                    "title": row.get("title"),
                    "requirement_ids": row.get("requirement_ids", []),
                }
                for row in reference.get("capabilities", [])
                if isinstance(row, dict)
            ],
        }
        atomic_json(target, compact)
        files["capability-reference.v1.json"] = file_sha(target)
        authority_inputs[relative(root, capability_reference_path)] = normalized_file_sha(capability_reference_path)
    for row in readiness_summary.get("tasks", []):
        if not isinstance(row, dict):
            continue
        rel_path = str(row.get("readiness_path") or "").strip()
        if not rel_path:
            continue
        path = repo_path(root, rel_path)
        if path.is_file():
            authority_inputs[rel_path] = normalized_file_sha(path)
    from _capability_task_evidence import CATALOG, encoding_mode, freeze_reference_catalog
    task_encoding = encoding_mode()
    if task_encoding == "lossless-v1":
        reference_rows = [row for path in task_view_paths for row in load_json(out_dir / "task-views" / path.name, [])]
        reference_rows.extend(load_json(out_dir / "semantic-requirements.v1.json", {}).get("requirements", []))
        catalog = freeze_reference_catalog(root.resolve(), reference_rows)
        atomic_json(out_dir / CATALOG, catalog)
        files[CATALOG] = file_sha(out_dir / CATALOG)
        for entries in catalog.values():
            for target in entries.values():
                if target["status"] == "valid":
                    authority_inputs[target["path"]] = normalized_file_sha(repo_path(root, target["path"]))
    index = {
        "schema_version": "newrouge.planning-analysis-input.v1",
        "source_revision": ledger.get("source_revision") or manifest.get("source_revision"),
        # Commit/dirty-worktree metadata is provenance only. It is deliberately
        # excluded from the content identity below so advancing local main does
        # not invalidate an otherwise identical planning input bundle.
        "repository_identity": dict(repository_identity or {}),
        "source_manifest_sha256": ledger.get("source_manifest_sha256") or manifest.get("manifest_sha256"),
        "files": files,
        "blinded_fields": sorted(SENSITIVE_CAPABILITY_KEYS),
        "blinding_transformations": transformations,
        "authority_inputs": authority_inputs,
        "model_batch_index": batch_index,
        "source_declared_classification": classification,
    }
    if task_encoding != "raw":
        index["task_view_encoding"] = task_encoding
    identity_content = dict(index)
    identity_content.pop("repository_identity", None)
    index["analysis_identity_sha256"] = canonical_sha(identity_content)
    atomic_json(out_dir / "analysis-index.json", index)
    return index


def parse_model_json(path: Path) -> dict[str, Any]:
    text = path.read_text(encoding="utf-8").strip()
    if text.startswith("~~~") or text.startswith("```"):
        lines = text.splitlines()
        if len(lines) >= 2:
            lines = lines[1:]
        if lines and (lines[-1].strip().startswith("~~~") or lines[-1].strip().startswith("```")):
            lines = lines[:-1]
        text = "\n".join(lines).strip()
    try:
        payload = json.loads(text)
    except json.JSONDecodeError as exc:
        preview = " ".join(text.split())[:240]
        raise ValueError(
            f"model output is not valid JSON at line {exc.lineno}, column {exc.colno}: {preview}"
        ) from exc
    if not isinstance(payload, dict):
        raise ValueError("model output must be a JSON object")
    return payload


def validate_output_schema(output_path: Path, schema_path: Path) -> None:
    """Reject a runner response that does not satisfy its host-supplied schema."""
    payload = json.loads(output_path.read_text(encoding="utf-8"))
    schema = json.loads(schema_path.read_text(encoding="utf-8"))
    try:
        import jsonschema  # type: ignore
    except ImportError:
        required = schema.get("required", []) if isinstance(schema, dict) else []
        if not isinstance(payload, dict) or any(key not in payload for key in required):
            raise ValueError("model output does not satisfy required JSON schema fields")
        return
    errors = sorted(jsonschema.Draft202012Validator(schema).iter_errors(payload),
                    key=lambda error: list(error.absolute_path))
    if errors:
        details = "; ".join(error.message for error in errors[:8])
        raise ValueError(f"model output does not satisfy JSON schema: {details}")


def _runner_prefix(executable: Path, *, suppress_bytecode: bool = False) -> list[str]:
    if executable.suffix.casefold() == ".py":
        return [sys.executable, *(["-B"] if suppress_bytecode else []), str(executable)]
    return [str(executable)]


def inspect_isolated_runner(executable: Path, *, suppress_bytecode: bool = False) -> dict[str, Any]:
    proc = subprocess.run(
        [*_runner_prefix(executable, suppress_bytecode=suppress_bytecode), "--describe"],
        text=True,
        encoding="utf-8",
        errors="replace",
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        timeout=30,
    )
    if proc.returncode != 0:
        raise ValueError(f"isolation runner describe failed: {proc.stdout.strip()}")
    payload = json.loads(proc.stdout)
    validate_runner_description(payload)
    return payload


def validate_runner_description(payload: dict[str, Any]) -> None:
    if payload.get("schema_version") != RUNNER_SCHEMA:
        raise ValueError("unsupported isolation runner schema")
    if payload.get("filesystem_scope") not in {"workspace_only", "prompt_only"}:
        raise ValueError("formal Capability generation requires workspace-only or prompt-only input")
    if payload.get("fresh_session_per_invocation") is not True:
        raise ValueError("formal Capability generation requires a fresh model session per invocation")
    if payload.get("can_read_outside_workspace") is not False:
        raise ValueError("formal Capability generation rejects runners that can read outside the workspace")
    if not str(payload.get("model") or "").strip():
        raise ValueError("isolation runner must report the model identity")
    if payload.get("model_tools") != []:
        raise ValueError("formal Capability generation requires a no-tools model session")


def _cancel_owned_pipe_io(workers: list[threading.Thread]) -> None:
    """Cancel blocking Windows pipe IO only on this process's recorded workers."""
    if os.name != "nt":
        return
    import ctypes
    from ctypes import wintypes
    kernel = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel.OpenThread.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
    kernel.OpenThread.restype = wintypes.HANDLE
    kernel.GetProcessIdOfThread.argtypes = [wintypes.HANDLE]
    kernel.GetProcessIdOfThread.restype = wintypes.DWORD
    kernel.CancelSynchronousIo.argtypes = [wintypes.HANDLE]
    kernel.CancelSynchronousIo.restype = wintypes.BOOL
    kernel.CloseHandle.argtypes = [wintypes.HANDLE]
    kernel.CloseHandle.restype = wintypes.BOOL
    for worker in workers:
        if not worker.is_alive() or worker.native_id is None:
            continue
        # THREAD_TERMINATE permits IO cancellation, not thread termination here.
        handle = kernel.OpenThread(0x0001 | 0x0800, False, worker.native_id)
        if not handle:
            continue
        try:
            if worker.is_alive() and kernel.GetProcessIdOfThread(handle) == os.getpid():
                kernel.CancelSynchronousIo(handle)
        finally:
            kernel.CloseHandle(handle)


class _WindowsRunnerOutput:
    """Own one merged stdout reader so timeout cleanup never closes its active IO."""
    def __init__(self, proc):
        self.proc = proc
        self.output = None
        self.error = None
        self.parts = []
        self.done = threading.Event()
        self.worker = threading.Thread(target=self._read, daemon=True, name="planning-runner-output")
        self.worker.start()

    def _read(self):
        text_mode = getattr(self.proc.stdout, "encoding", None) is not None
        stream = self.proc.stdout.buffer if text_mode else self.proc.stdout
        try:
            # read1 returns each available successful OS read; a later cancelled
            # read must not discard bytes already delivered before the timeout.
            while True:
                part = stream.read1(65536)
                if not part:
                    break
                self.parts.append(part)
        except (OSError, ValueError) as error:
            self.error = error
        finally:
            try:
                raw = b"".join(self.parts)
                self.output = (raw.decode(self.proc.stdout.encoding, errors=self.proc.stdout.errors)
                    .replace("\r\n", "\n").replace("\r", "\n")) if text_mode else raw
            finally:
                try:
                    self.proc.stdout.close()
                finally:
                    self.done.set()

    def communicate(self, timeout):
        deadline = time.monotonic() + timeout
        if not self.done.wait(timeout):
            raise subprocess.TimeoutExpired(self.proc.args, timeout)
        if self.error is not None:
            raise self.error
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise subprocess.TimeoutExpired(self.proc.args, timeout, output=self.output)
        self.proc.wait(timeout=remaining)
        return self.output, None

    def cancel(self):
        _cancel_owned_pipe_io([self.worker])
        self.worker.join(timeout=0.5)
        if self.worker.is_alive():
            # Never close the buffered stream from another thread while read holds it.
            raise RuntimeError("isolated model runner pipe cleanup incomplete")
        self.proc.wait(timeout=0.5)
        return self.output


def _terminate_process_tree(proc: subprocess.Popen[str]) -> None:
    if proc.poll() is not None:
        return
    if os.name == "nt":
        try:
            subprocess.run(
                ["taskkill", "/PID", str(proc.pid), "/T", "/F"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=15,
                check=False,
            )
            if proc.poll() is not None:
                return
            proc.kill()
            return
        except (OSError, subprocess.SubprocessError):
            proc.kill()
            return
    try:
        os.killpg(proc.pid, signal.SIGKILL)
    except (OSError, ProcessLookupError):
        proc.kill()


def run_isolated_model(
    executable: Path,
    *,
    workspace: Path,
    prompt_path: Path,
    output_path: Path,
    timeout_sec: int,
    synthesis_timeout_sec: int | None = None,
    output_schema: Path | None = None,
    model_request_budget: int | None = None,
    execution_log: Path | None = None,
    wall_timeout_sec: int | None = None,
    suppress_bytecode: bool = False,
) -> dict[str, Any]:
    cmd = [
        *_runner_prefix(executable, suppress_bytecode=suppress_bytecode),
        "--workspace", str(workspace),
        "--prompt-file", str(prompt_path),
        "--output", str(output_path),
        "--timeout-sec", str(timeout_sec),
    ]
    if synthesis_timeout_sec is not None:
        cmd.extend(["--synthesis-timeout-sec", str(max(1, int(synthesis_timeout_sec)))])
    if output_schema is not None:
        cmd.extend(["--output-schema", str(output_schema)])
    if model_request_budget is not None:
        cmd.extend(["--model-request-budget", str(max(0, int(model_request_budget)))])
    kwargs: dict[str, Any] = {
        "text": True,
        "encoding": "utf-8",
        "errors": "replace",
        "stdout": subprocess.PIPE,
        "stderr": subprocess.STDOUT,
    }
    if os.name == "nt":
        kwargs["creationflags"] = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
    else:
        kwargs["start_new_session"] = True
    if execution_log is not None:
        # The audit must retain exact OS output bytes, even for malformed UTF-8.
        kwargs["text"] = False
        kwargs.pop("encoding")
        kwargs.pop("errors")
    started = time.monotonic()
    try:
        proc = subprocess.Popen(cmd, **kwargs)
    except OSError:
        if execution_log is not None:
            atomic_json(execution_log, {"command": cmd, "returncode": None, "status": "launch_failed",
                "runner_dispatch_count": 0, "active_elapsed_seconds": time.monotonic() - started,
                "stdout_base64": "", "stdout": ""})
        raise
    def persist_execution(stdout: str | bytes, status: str, *, original_error=None, cleanup_errors=()) -> None:
        if execution_log is not None:
            raw = stdout if isinstance(stdout, bytes) else stdout.encode("utf-8")
            atomic_json(execution_log, {"command": cmd, "returncode": proc.returncode,
                "status": status, "runner_dispatch_count": 1,
                "active_elapsed_seconds": time.monotonic() - started,
                "stdout_base64": base64.b64encode(raw).decode("ascii"),
                "stdout": raw.decode("utf-8", errors="replace"),
                **({"original_error": {"type": type(original_error).__name__, "detail": str(original_error)},
                    "cleanup_errors": cleanup_errors} if original_error is not None else {})})
    def cleanup_after_error(error, status):
        # Cleanup is best effort, but every failure and every byte already read
        # must survive it. In particular cancel() may itself time out or raise.
        failures = []
        stdout = (getattr(error, "output", None) or (b"" if execution_log is not None else ""))
        try:
            _terminate_process_tree(proc)
        except BaseException as cleanup_error:
            failures.append({"stage": "terminate", "type": type(cleanup_error).__name__, "detail": str(cleanup_error)})
        try:
            if capture is not None:
                stdout = capture.cancel()
            else:
                stdout, _ = proc.communicate(timeout=15)
        except BaseException as cleanup_error:
            failures.append({"stage": "capture", "type": type(cleanup_error).__name__, "detail": str(cleanup_error)})
            # The reader appends only completed reads. Take one immutable snapshot
            # even if it has not reached EOF; never wait on its buffered lock.
            if capture is not None:
                stdout = b"".join(tuple(capture.parts))
            elif getattr(cleanup_error, "output", None) is not None:
                stdout = cleanup_error.output
        finally:
            persist_execution(stdout or (b"" if execution_log is not None else ""), status,
                original_error=error, cleanup_errors=failures)
        return stdout or (b"" if execution_log is not None else "")
    capture = None
    try:
        effective_timeout = (max(timeout_sec + max(0, synthesis_timeout_sec or 0) + 30, 60)
                             if wall_timeout_sec is None else max(1, wall_timeout_sec))
        capture = _WindowsRunnerOutput(proc) if os.name == "nt" else None
        stdout, _stderr = (capture.communicate(effective_timeout) if capture is not None else
                           proc.communicate(timeout=effective_timeout))
    except subprocess.TimeoutExpired as exc:
        stdout = cleanup_after_error(exc, "timeout")
        raise TimeoutError(
            f"isolated model runner timed out after {effective_timeout}s: {stdout[-2000:]}"
        ) from exc
    except BaseException as exc:
        cleanup_after_error(exc, "interrupted")
        raise
    persist_execution(stdout, "completed" if proc.returncode == 0 else "failed")
    if isinstance(stdout, bytes):
        stdout = stdout.decode("utf-8", errors="strict")
    if proc.returncode != 0:
        raise RuntimeError(f"isolated model runner failed: {stdout.strip()}")
    if not output_path.is_file():
        raise RuntimeError("isolated model runner produced no output")
    if output_schema is not None:
        validate_output_schema(output_path, output_schema)
    receipt = {}
    for line in reversed(stdout.splitlines()):
        line = line.strip()
        if line.startswith("{") and line.endswith("}"):
            try:
                candidate = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(candidate, dict):
                receipt = candidate
                break
    return receipt
